// 1. Fetch live rates dynamically from the earlier HTTP Request node
// (Ensure your HTTP Request node is exactly named "HTTP Request")
const liveRates = $('Fetch Live Exchange Rates').first().json.data;

const items = $input.all();
let index = 1;

for (const item of items) {
  const row = item.json;

  // 2. Normalize Price to a Base Currency (USD) using the live API data
  const currency = row.currency ? row.currency.toUpperCase() : "USD";

  // By default, FreeCurrencyAPI bases against USD. 
  // Formula: Amount / Currency Rate = USD Equivalent
  const exchangeRate = liveRates[currency] || 1;
  const normalized_price = Math.round((row.quoted_price / exchangeRate) * 100) / 100;

  // 3. Normalize Delivery Time to Days
  let duration = row.delivery_duration || 0;
  let unit = row.delivery_unit ? row.delivery_unit.toLowerCase().trim() : "days";
  let normalized_days = duration;

  if (unit === "months" || unit === "month") {
    normalized_days = duration * 30;
  } else if (unit === "weeks" || unit === "week") {
    normalized_days = duration * 7;
  }

  // 4. Prepare for "Blind" AI Evaluation (Bias Reduction)
  const blind_alias = `Supplier_${index}`;

  // 5. Overwrite payload
  item.json = {
    blind_alias: blind_alias,
    original_supplier_id: row.supplier_id,
    normalized_price_usd: normalized_price,
    normalized_delivery_days: normalized_days,
    compliance_flags: row.compliance_certifications,
    qualitative_proposal: row.qualitative_proposal_text
  };

  index++;
}

return items;

