const aiResults = $input.all();
const normalizedData = $('Normalize & Anonymize Data').all(); // Ensure this matches your first node name

let evaluatedBids = [];
let prices = [];
let speeds = [];

// 1. Merge data and compute Quality Score with Risk Penalty
for (let i = 0; i < aiResults.length; i++) {
  const ai = aiResults[i].json; 
  const original = normalizedData[i].json;

  let qualityScore = (ai.sla_score + ai.support_score + ai.compliance_score) / 3;
  if (ai.risk_flag) qualityScore = qualityScore * 0.5;

  evaluatedBids.push({
    alias: original.blind_alias,
    supplier_id: original.original_supplier_id,
    price: original.normalized_price_usd,
    days: original.normalized_delivery_days,
    quality_score: parseFloat(qualityScore.toFixed(1)),
    risk_flag: ai.risk_flag,
    justification: ai.ai_justification
  });

  prices.push(original.normalized_price_usd);
  speeds.push(original.normalized_delivery_days);
}

const minPrice = Math.min(...prices);
const minDays = Math.min(...speeds);

// 2. Calculate Scenarios and Normalized Scores
let scoredBids = evaluatedBids.map(bid => {
  const priceScore = (minPrice / bid.price) * 10; 
  const speedScore = (minDays / bid.days) * 10;

  const scenarios = {
    standard: (priceScore * 0.40) + (bid.quality_score * 0.30) + (speedScore * 0.30),
    cost_optimized: (priceScore * 0.70) + (bid.quality_score * 0.15) + (speedScore * 0.15),
    risk_averse: (priceScore * 0.20) + (bid.quality_score * 0.60) + (speedScore * 0.20),
    speed_to_market: (priceScore * 0.20) + (bid.quality_score * 0.20) + (speedScore * 0.60)
  };

  for (let key in scenarios) { scenarios[key] = parseFloat(scenarios[key].toFixed(2)); }

  return {
    ...bid,
    price_score: parseFloat(priceScore.toFixed(1)),
    speed_score: parseFloat(speedScore.toFixed(1)),
    scenarios: scenarios
  };
});

// 3. Sort by Standard Scenario to establish baseline ranking
scoredBids.sort((a, b) => b.scenarios.standard - a.scenarios.standard);

// 4. Assign explicit Rank and expose explicit Scenario Winners (Fixes gaps 4 & 5)
const finalRankings = scoredBids.map((bid, index) => {
  return {
    json: {
      rank: index + 1, // Explicit rank assignment
      ...bid,
      is_high_risk: bid.risk_flag ? "FLAGGED: Security/Compliance Gap" : "Clear"
    }
  };
});

// 5. Shortlist: Restrict output strictly to Top 3 (Fixes gap 3)
// Remove .slice(0, 3) if you want to keep all suppliers
return finalRankings.slice(0, 3);

